#![expect(
    clippy::print_stdout,
    reason = "example output is the point of the example"
)]

//! Example demonstrating the performant static schema parser API.
//!
//! This example shows using the `provider_schema!` macro which can be auto-generated using the
//! generate-provider tool.
//!
//! # Requirements
//!
//! Must be run as Administrator for kernel tracing.
//!
//! # Usage
//!
//! ```bash
//! cargo run --example 02_static_schema
//! ```

use etw::{CP_ACP, Guid, Trace, provider_schema};
use std::time::Duration;

const PROCESS_GUID: Guid = Guid::from_u128(0x22fb2cd6_0e7b_422b_a0c7_2fad1fd0e716);
const KEYWORD_PROCESS: u64 = 0x10;
const PROCESS_START: u16 = 1;
const PROCESS_STOP: u16 = 2;

// BEGIN Auto-generated by etw-rs generate-provider.
// generate-provider Microsoft-Windows-Kernel-Process --event-only 1 2 --query-release
// --drop-old-versions
//
// Hand-edited since: ProcessStart version 2 was removed to keep the example short,
// and a regeneration will bring it back.
provider_schema! {
    guid: Guid::from_u128(0x22fb2cd6_0e7b_422b_a0c7_2fad1fd0e716),
    events: {
        event { // ProcessStart [WINEVENT_KEYWORD_PROCESS]
            id: 1,
            name: "ProcessStart",
            // version { 2, ... } — removed, Windows 10 1511-1809 are EOL
            version { 3, fields: { // Since Windows 10 1903
                ProcessID: u32,                   // [0] UInt32
                ProcessSequenceNumber: u64,       // [1] UInt64
                CreateTime: u64 @ tdh(FileTime),  // [2] FileTime
                ParentProcessID: u32,             // [3] UInt32
                ParentProcessSequenceNumber: u64, // [4] UInt64
                SessionID: u32,                   // [5] UInt32
                Flags: u32,                       // [6] UInt32
                ProcessTokenElevationType: u32,   // [7] UInt32
                ProcessTokenIsElevated: u32,      // [8] UInt32
                MandatoryLabel: SidRef,           // [9] SID
                ImageName: WideStrRef,            // [10] UnicodeString
                ImageChecksum: u32,               // [11] UInt32
                TimeDateStamp: u32,               // [12] UInt32
                PackageFullName: WideStrRef,      // [13] UnicodeString
                PackageRelativeAppId: WideStrRef, // [14] UnicodeString
            }}
            version { 4, extends_version: 3, fields: { // Since Windows 11 24H2
                SecurityMitigations: u32, // [15] UInt32
            }}
        }
        event { // ProcessStop [WINEVENT_KEYWORD_PROCESS]
            id: 2,
            name: "ProcessStop",
            // version { 1, ... } — removed, Windows 10 1511-1809 are EOL
            version { 2, fields: { // Since Windows 10 1903
                ProcessID: u32,                  // [0] UInt32
                ProcessSequenceNumber: u64,      // [1] UInt64
                CreateTime: u64 @ tdh(FileTime), // [2] FileTime
                ExitTime: u64 @ tdh(FileTime),   // [3] FileTime
                ExitCode: u32,                   // [4] UInt32
                TokenElevationType: u32,         // [5] UInt32
                HandleCount: u32,                // [6] UInt32
                CommitCharge: u64,               // [7] UInt64
                CommitPeak: u64,                 // [8] UInt64
                CPUCycleCount: u64,              // [9] UInt64
                ReadOperationCount: u32,         // [10] UInt32
                WriteOperationCount: u32,        // [11] UInt32
                ReadTransferKiloBytes: u32,      // [12] UInt32
                WriteTransferKiloBytes: u32,     // [13] UInt32
                HardFaultCount: u32,             // [14] UInt32
                ImageName: AnsiStrRef,           // [15] AnsiString
            }}
        }
    }
}
// END Auto-generated by etw-rs generate-provider.

fn main() -> etw::Result<()> {
    println!("Static Schema Example - Process Start/Stop Events");

    // **Most** ETW providers are properly versioned.
    //
    // This means that we can use the versioned schema from one system everywhere.
    // And the compiler can generate efficient static code for that schema rather than
    // dynamic dispatch based on the runtime schema.
    //
    // The (generated) `provider_schema!` block above creates a `ProcessStartParser` and a
    // `ProcessStopParser`. These efficiently handle all declared versions plus fallback to
    // dynamic lookup for future versions.
    // Fields not present in the actual event version return Err(PropertyNotFound).
    //
    // Of course, it still makes sense to validate our hardcoded offsets against the registered
    // versions at runtime. The benefit is that we do this once - not on every event.
    etw::validate_all_schemas()?;

    // **Most** ETW providers retain ordering of pre-existing fields across versions.
    //
    // The dynamic fallback internally will optimistically use the index hint from the last known
    // version.

    let mut trace = Trace::new("static_schema")?;
    trace.enable_provider(PROCESS_GUID, KEYWORD_PROCESS)?;

    trace.set_event_callback(move |event, context| {
        match (event.provider_guid(), event.id()) {
            (PROCESS_GUID, PROCESS_START) => {
                let mut parser = ProcessStartParser::new(event, context)?;

                let pid = parser.ProcessID()?;

                // Note: ETW has two string types - UTF-16LE unicode strings (wide strings) and ANSI
                // strings. Wide strings convert losslessly to `OsString`, since Windows permits
                // unpaired surrogates that a UTF-8 `String` cannot hold. ANSI strings convert to
                // `String` using the active code page, propagating any decoding errors.
                let image_name = parser.ImageName()?.display().to_string();

                // SecurityMitigations was added in V4 — use a version check or handle
                // Err(PropertyNotFound).
                if event.version() >= 4 {
                    let m = parser.SecurityMitigations()?;
                    println!("  Start: PID={pid} mitigations=0x{m:x} {image_name}");
                } else {
                    println!("  Start: PID={pid} {image_name}");
                }
            }
            (PROCESS_GUID, PROCESS_STOP) => {
                let mut parser = ProcessStopParser::new(event, context)?;

                let pid = parser.ProcessID()?;
                let exit_code = parser.ExitCode()?;

                // WARNING: Converting to UTF-8 too early may introduce unexpected behaviours for
                // some use cases. For example, NTFS performs case-insensitive equality checks using
                // UTF-16 code units with a fixed, filesystem-defined case-folding table ($UpCase),
                // without normalisation.
                //
                // Variable-length types can also be accessed by reference to avoid copying.
                // This is the mechanism to access the raw pre-conversion string data.
                // This supports early filtering scenarios, and explicit decoding scenarios.
                //
                // ProcessStop's ImageName is the kernel's short image name, truncated to 15
                // characters — unlike ProcessStart's full path.
                let image_name_ref = parser.ImageName_ref()?;
                let image_name = image_name_ref.decode(CP_ACP)?;

                println!("  Stop:  PID={pid} exit={exit_code} {image_name}");
            }
            _ => {}
        }

        Ok(())
    });

    trace.start_processing_thread()?;
    std::thread::sleep(Duration::from_secs(5));

    Ok(())
}
